CREATE TABLE IF NOT EXISTS contract_comparisons(id INT AUTO_INCREMENT PRIMARY KEY,contract_id INT NOT NULL,old_version_id INT NOT NULL,new_version_id INT NOT NULL,added_count INT NOT NULL,removed_count INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(contract_id) REFERENCES contracts(id) ON DELETE RESTRICT,FOREIGN KEY(old_version_id) REFERENCES contract_versions(id),FOREIGN KEY(new_version_id) REFERENCES contract_versions(id))ENGINE=InnoDB;
